INSERT INTO skills (id,owner_id,slug,full_id,name,description,license,compatibility,allowed_tools,source_type,source_url,status,download_count,star_count,created_at,updated_at,published_at,repo_id,author_name,author_url,author_avatar_url,author_slug,category,tags,is_private) VALUES ('d6a54ad8-ddcc-419c-b2d6-71ad3789fa8e','a009b543-fd95-5438-a1ca-d00e12c24323','TF-differential-binding','BIsnake2001/ChromSkills/TF-differential-binding','TF-differential-binding','The TF-differential-binding pipeline performs differential transcription factor (TF) binding analysis from ChIP-seq datasets (TF peaks) using the DiffBind package in R. It identifies genomic regions where TF binding intensity significantly differs between experimental conditions (e.g., treatment vs. control, mutant vs. wild-type). Use the TF-differential-binding pipeline when you need to analyze the different function of the same TF across two or more biological conditions, cell types, or treatments using ChIP-seq data or TF binding peaks. This pipeline is ideal for studying regulatory mechanisms that underlie transcriptional differences or epigenetic responses to perturbations.',NULL,NULL,NULL,'github','https://github.com/BIsnake2001/ChromSkills/tree/master/9.TF-differential-binding','approved','0','0','2026-01-19 13:40:00.689659+00','2026-01-25 12:03:23.642745+00',NULL,'BIsnake2001/ChromSkills','BIsnake2001','https://github.com/BIsnake2001','https://avatars.githubusercontent.com/u/106907576?v=4','bisnake2001','data-processing','{analytics,data-processing,statistics,automation,tooling}','f') ON CONFLICT (id) DO NOTHING;
