INSERT INTO skills (id,owner_id,slug,full_id,name,description,license,compatibility,allowed_tools,source_type,source_url,status,download_count,star_count,created_at,updated_at,published_at,repo_id,author_name,author_url,author_avatar_url,author_slug,category,tags,is_private) VALUES ('fe8e8ee8-3c09-45b6-9d92-f358e7902ea0','2e3c8910-713b-5687-88fc-48c360d81593','api-security','williamzujkowski/standards/api-security','api-security','1. Broken Object Level Authorization (BOLA) - API fails to validate user access to objects 2. Broken Authentication - Weak or missing authentication mechanisms 3. Broken Object Property Level Authorization - Missing field-level access control 4. Unrestricted Resource Consumption - No rate limiting or throttling 5. Broken Function Level Authorization - Missing authorization checks on endpoints 6. Unrestricted Access to Sensitive Business Flows - Automated abuse of legitimate workflows 7. Server Side Request Forgery (SSRF) - API accepts URLs without validation 8. Security Misconfiguration - Insecure default configs, verbose errors 9. Improper Inventory Management - Undocumented/deprecated APIs in production 10. Unsafe Consumption of APIs - Trusting third-party API data without validation',NULL,NULL,NULL,'github','https://github.com/williamzujkowski/standards/tree/master/skills/security/api-security','approved','0','0','2026-01-20 00:00:02.993026+00','2026-01-26 10:08:22.419374+00',NULL,'williamzujkowski/standards','williamzujkowski','https://github.com/williamzujkowski','https://avatars.githubusercontent.com/u/14303249?v=4','williamzujkowski','security','{security,api-integration,vulnerability-assessment,authentication,backend}','f') ON CONFLICT (id) DO NOTHING;
